/** Map keyed by description for O(1) admin-UI lookups. */
export const OG_GTOON_POWER_CATALOG_BY_DESCRIPTION = new Map(
  OG_GTOON_POWER_CATALOG.map(e => [e.description, e])
)

/** Looks up a catalog entry by its exact description string, or null if not found ("No Power" included). */
export function lookupPower(description) {
  if (!description) return null
  return OG_GTOON_POWER_CATALOG_BY_DESCRIPTION.get(description) || null
}
